import{_ as r,c as l,o as i,ah as t,ai as e}from"./chunks/framework.5ZZXabC7.js";const b=JSON.parse('{"title":"장정호","description":"","frontmatter":{},"headers":[],"relativePath":"portfolio/index.md","filePath":"portfolio/index.md","lastUpdated":1756890187000}'),o={name:"portfolio/index.md"};function n(s,a,h,g,d,p){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="장정호" tabindex="-1">장정호 <a class="header-anchor" href="#장정호" aria-label="Permalink to “장정호”">​</a></h1><p><img src="'+e+'" alt="프로필 이미지"></p><p>안녕하세요! 코드 짜는 걸 좋아하는 개발자 장정호입니다.</p><p>새로운 기술 배우는 것도 좋지만, 배운 걸로 뭔가 실제로 만들어보는 게 더 재밌어요.<br> 완벽하지 않아도 일단 만들어보고, &quot;이거 왜 안되지?&quot; 하면서 고쳐나가는 걸 좋아합니다.</p><hr><h2 id="나는-이런-개발자예요" tabindex="-1">나는 이런 개발자예요 <a class="header-anchor" href="#나는-이런-개발자예요" aria-label="Permalink to “나는 이런 개발자예요”">​</a></h2><p><strong>&quot;일단 해보는 개발자&quot;</strong></p><p>새로운 기술 나오면 문서보다는 예제부터 따라해보는 스타일이에요.<br> 에러 나도 &quot;아 또 에러다&quot; 하면서 오히려 재밌어해요. 문제 하나씩 해결하는 과정이 퍼즐 맞추기 같거든요.</p><hr><h2 id="주로-사용하는-기술들" tabindex="-1">주로 사용하는 기술들 <a class="header-anchor" href="#주로-사용하는-기술들" aria-label="Permalink to “주로 사용하는 기술들”">​</a></h2><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to “Frontend”">​</a></h3><ul><li><strong>JavaScript (ES6+)</strong> - 가장 자주 쓰고 가장 편한 언어</li><li><strong>React</strong> - 컴포넌트 기반 사고에 익숙해진 상태</li><li><strong>TypeScript</strong> - 타입 에러 잡는 재미를 알게 된 후 적극 활용</li><li><strong>HTML/CSS</strong> - 기본기는 탄탄하다고 자부함</li><li><strong>Tailwind CSS</strong> - 빠른 스타일링을 위해 최근 주로 사용</li></ul><h3 id="개발-환경-도구" tabindex="-1">개발 환경 &amp; 도구 <a class="header-anchor" href="#개발-환경-도구" aria-label="Permalink to “개발 환경 &amp; 도구”">​</a></h3><ul><li><strong>Git/GitHub</strong> - 버전 관리와 협업의 기본</li><li><strong>VS Code</strong> - 수많은 익스텐션과 함께하는 개발 환경</li><li><strong>Vite</strong> - 빠른 개발 서버가 주는 쾌감</li><li><strong>Chrome DevTools</strong> - 디버깅의 든든한 파트너</li></ul><h3 id="현재-관심사" tabindex="-1">현재 관심사 <a class="header-anchor" href="#현재-관심사" aria-label="Permalink to “현재 관심사”">​</a></h3><ul><li><strong>Next.js</strong> - React 기반 풀스택 개발에 도전해보고 싶어서</li><li><strong>성능 최적화</strong> - 사용자가 체감할 수 있는 속도 개선</li><li><strong>테스트 코드</strong> - 안정적인 코드를 위한 필수 스킬</li></ul><hr><h2 id="개발하며-중요하게-생각하는-것들" tabindex="-1">개발하며 중요하게 생각하는 것들 <a class="header-anchor" href="#개발하며-중요하게-생각하는-것들" aria-label="Permalink to “개발하며 중요하게 생각하는 것들”">​</a></h2><h3 id="코드-품질" tabindex="-1">코드 품질 <a class="header-anchor" href="#코드-품질" aria-label="Permalink to “코드 품질”">​</a></h3><ul><li><strong>읽기 쉬운 코드</strong> - 6개월 후의 나도 이해할 수 있는 코드</li><li><strong>일관된 스타일</strong> - 팀원들과 약속한 규칙은 반드시 지키기</li><li><strong>적절한 주석</strong> - 왜 이렇게 작성했는지에 대한 기록</li></ul><h3 id="협업-스타일" tabindex="-1">협업 스타일 <a class="header-anchor" href="#협업-스타일" aria-label="Permalink to “협업 스타일”">​</a></h3><ul><li><strong>솔직한 소통</strong> - 모르는 건 모른다고, 어려운 건 어렵다고 말하기</li><li><strong>적극적인 질문</strong> - 혼자 해결하려다 시간 낭비하지 않기</li><li><strong>건설적인 피드백</strong> - 비판보다는 개선 방향 제시</li></ul><h3 id="문제-해결-방식" tabindex="-1">문제 해결 방식 <a class="header-anchor" href="#문제-해결-방식" aria-label="Permalink to “문제 해결 방식”">​</a></h3><ul><li><strong>작은 단위로 나누기</strong> - 큰 문제를 작은 문제들로 분해</li><li><strong>검색과 문서 활용</strong> - 구글링과 공식 문서 읽기 능숙</li><li><strong>직접 실험해보기</strong> - 이론보다는 실제로 코드를 작성해서 확인</li></ul><hr><h2 id="개발자가-되기까지" tabindex="-1">개발자가 되기까지 <a class="header-anchor" href="#개발자가-되기까지" aria-label="Permalink to “개발자가 되기까지”">​</a></h2><h3 id="프로그래밍-시작-계기" tabindex="-1">프로그래밍 시작 계기 <a class="header-anchor" href="#프로그래밍-시작-계기" aria-label="Permalink to “프로그래밍 시작 계기”">​</a></h3><p>대학교에서 처음 배운 C언어가 너무 어려워서 포기할 뻔했는데,<br> 웹 개발을 처음 접했을 때 브라우저에서 바로 결과를 확인할 수 있는 점이 매력적이었습니다.</p><h3 id="주요-학습-경험" tabindex="-1">주요 학습 경험 <a class="header-anchor" href="#주요-학습-경험" aria-label="Permalink to “주요 학습 경험”">​</a></h3><p><strong>HTML/CSS 기초 다지기</strong> (2022년 초)</p><ul><li>처음엔 <code>div</code> 태그만 써도 뿌듯했던 시절</li><li>CSS로 레이아웃 잡는 게 퍼즐 맞추기 같아서 재밌었음</li></ul><p><strong>JavaScript와의 첫 만남</strong> (2022년 중)</p><ul><li>변수, 함수 개념부터 차근차근 학습</li><li>DOM 조작으로 웹페이지가 동적으로 변하는 걸 보고 감동</li></ul><p><strong>React 생태계 탐험</strong> (2023년 초~현재)</p><ul><li>컴포넌트 기반 사고로 개발 방식이 완전히 바뀜</li><li>Hooks, Context API 등을 배우며 상태 관리의 중요성 깨달음</li></ul><p><strong>TypeScript 도입</strong> (2023년 하반기)</p><ul><li>처음엔 귀찮았지만, 타입 에러로 버그를 미리 잡는 경험 후 필수가 됨</li><li>협업 시 코드의 의도를 명확히 전달할 수 있어 좋음</li></ul><hr><h2 id="만들어본-프로젝트들" tabindex="-1">만들어본 프로젝트들 <a class="header-anchor" href="#만들어본-프로젝트들" aria-label="Permalink to “만들어본 프로젝트들”">​</a></h2><h3 id="할-일-관리-앱" tabindex="-1">할 일 관리 앱 <a class="header-anchor" href="#할-일-관리-앱" aria-label="Permalink to “할 일 관리 앱”">​</a></h3><p><strong>왜 만들었나?</strong><br> 시중에 좋은 앱들이 많지만, 내가 원하는 기능만 딱 들어간 심플한 앱이 필요했어요.</p><p><strong>기술적 도전</strong></p><ul><li>React Hooks를 활용한 상태 관리</li><li>TypeScript로 컴포넌트 인터페이스 정의</li><li>localStorage를 활용한 데이터 지속성</li><li>Tailwind CSS로 반응형 디자인</li></ul><p><strong>배운 점</strong></p><ul><li>상태 관리의 복잡성과 Context API의 유용함</li><li>TypeScript가 런타임 에러를 줄여주는 경험</li><li>사용자 경험을 고려한 UI/UX 디자인의 중요성</li></ul><p><a href="/projects/todo-app.html">자세히 보기</a> | <a href="https://github.com/jang-oi/todo-app" target="_blank" rel="noreferrer">GitHub 코드</a></p><hr><h3 id="vitepress-포트폴리오-현재-보고-있는-사이트" tabindex="-1">VitePress 포트폴리오 (현재 보고 있는 사이트!) <a class="header-anchor" href="#vitepress-포트폴리오-현재-보고-있는-사이트" aria-label="Permalink to “VitePress 포트폴리오 (현재 보고 있는 사이트!)”">​</a></h3><p><strong>왜 만들었나?</strong><br> 단순한 정적 사이트가 아닌, 마크다운으로 쉽게 콘텐츠를 추가할 수 있는 블로그 형태가 필요했어요.</p><p><strong>기술적 도전</strong></p><ul><li>VitePress 설정과 커스터마이징</li><li>GitHub Actions를 통한 자동 배포</li><li>SEO 최적화와 다국어 지원 구조</li><li>마크다운 기반 콘텐츠 관리 시스템</li></ul><p><strong>배운 점</strong></p><ul><li>정적 사이트 생성기의 장점과 활용법</li><li>CI/CD 파이프라인 구축 경험</li><li>기술 블로그 운영의 가치</li></ul><p><a href="https://github.com/jang-oi/portfolio" target="_blank" rel="noreferrer">GitHub 코드</a></p><h2 id="앞으로의-계획" tabindex="-1">앞으로의 계획 <a class="header-anchor" href="#앞으로의-계획" aria-label="Permalink to “앞으로의 계획”">​</a></h2><h3 id="당장-해보고-싶은-것들" tabindex="-1">당장 해보고 싶은 것들 <a class="header-anchor" href="#당장-해보고-싶은-것들" aria-label="Permalink to “당장 해보고 싶은 것들”">​</a></h3><ul><li><strong>Next.js 프로젝트</strong> - React 기반 풀스택 개발 경험해보기</li><li><strong>팀 프로젝트 참여</strong> - 혼자가 아닌 여러 명과 함께 개발하는 경험</li><li><strong>오픈소스 기여</strong> - 작은 것부터 시작해서 커뮤니티에 참여</li><li><strong>테스트 코드 작성</strong> - 안정적인 코드를 위한 필수 스킬 익히기</li></ul><h3 id="장기적인-목표" tabindex="-1">장기적인 목표 <a class="header-anchor" href="#장기적인-목표" aria-label="Permalink to “장기적인 목표”">​</a></h3><ul><li><strong>문제 해결 능력 향상</strong> - 어떤 문제든 차근차근 해결할 수 있는 개발자</li><li><strong>지식 공유</strong> - 배운 것을 다른 사람들과 나누는 개발자</li><li><strong>사용자 중심 사고</strong> - 기술보다 사용자 가치를 우선하는 개발자</li></ul><hr><h2 id="마지막으로" tabindex="-1">마지막으로 <a class="header-anchor" href="#마지막으로" aria-label="Permalink to “마지막으로”">​</a></h2><p>저의 포트폴리오를 봐주셔서 감사합니다!</p><p>아직 많이 부족하지만, 매일 조금씩 성장하려고 노력하고 있습니다.<br> 새로운 것을 배우는 것도 좋아하지만, 배운 것을 실제로 활용해서 문제를 해결하는 과정을 더 즐깁니다.</p><p><strong>함께 성장할 수 있는 기회가 있다면 언제든 연락해 주세요!</strong></p><p><strong>GitHub</strong>: <a href="https://github.com/jang-oi" target="_blank" rel="noreferrer">@jang-oi</a></p>',65)])])}const u=r(o,[["render",n]]);export{b as __pageData,u as default};
